===== ResolveOwnerRegistrationDate =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Establishes a new owner's effective registration date: defaulting to the server's current
 * date when the request did not supply one, then rolling a weekend date (whether supplied or
 * defaulted) forward to the next business day so the stored {@code registrationDate} always
 * falls on a weekday. Everything derived from it (e.g. the membership number's year segment,
 * the per-day create limit) therefore uses the adjusted date.
 */
public class ResolveOwnerRegistrationDate {

    public void service(@Val Owner owner) {
        LocalDate effective = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
        owner.setRegistrationDate(BusinessDays.rollForward(effective));
    }
}
===== AssignOwnerNamesakeCount =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many existing owners already shared this owner's name at creation time:
 * the count of owners with the same firstName and lastName (compared case-insensitively).
 * Computed before the new owner is saved, so it never counts itself.
 */
public class AssignOwnerNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (sameName(existing.getFirstName(), owner.getFirstName())
                    && sameName(existing.getLastName(), owner.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    private static boolean sameName(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}
===== AssignOwnerCustomerCode =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns a new owner's {@code customerCode} before it is saved. The code is
 * {@code <REGION>-<HASH8>} (see {@link OwnerCustomerCodes}): the region derived from the owner's
 * postcode and a hash of their telephone and last name, so it is a stable function of the owner's
 * own identity rather than a per-city sequence.
 */
public class AssignOwnerCustomerCode {

    public void service(@Val Owner owner) {
        owner.setCustomerCode(OwnerCustomerCodes.forOwner(owner));
    }
}
